package kome.common.data;
import net.minecraft.nbt.NBTTagCompound;
public final class KOMEDiplomacyRecord {
 public String factionA,factionB,requestingFaction="",receivingFaction="",requesterIdentity="",lastUpdatedBy=""; public KOMEDiplomacyRelation relation=KOMEDiplomacyRelation.NEUTRAL,pendingTarget; public long requestedAt,updatedAt;
 public KOMEDiplomacyRecord(String a,String b){String[] p=pair(a,b);factionA=p[0];factionB=p[1];}
 public String key(){return pairKey(factionA,factionB);} public static String pairKey(String a,String b){String[] p=pair(a,b);return p[0]+"|"+p[1];}
 private static String[] pair(String a,String b){String x=KOMEAlliance.normalizeFactionKey(a),y=KOMEAlliance.normalizeFactionKey(b);if(x.length()==0||y.length()==0||x.equals(y))throw new IllegalArgumentException("Diplomacy pair must contain two distinct factions");return x.compareTo(y)<0?new String[]{x,y}:new String[]{y,x};}
 public NBTTagCompound writeToNBT(){NBTTagCompound n=new NBTTagCompound();n.setString("FactionA",factionA);n.setString("FactionB",factionB);n.setString("Relation",relation.key);if(pendingTarget!=null){n.setString("PendingTarget",pendingTarget.key);n.setString("RequestingFaction",requestingFaction);n.setString("ReceivingFaction",receivingFaction);n.setString("RequesterIdentity",requesterIdentity);n.setLong("RequestedAt",requestedAt);}n.setString("LastUpdatedBy",lastUpdatedBy);n.setLong("UpdatedAt",updatedAt);return n;}
 public static KOMEDiplomacyRecord readFromNBT(NBTTagCompound n){KOMEDiplomacyRecord r=new KOMEDiplomacyRecord(n.getString("FactionA"),n.getString("FactionB"));r.relation=KOMEDiplomacyRelation.parse(n.getString("Relation"));if(n.hasKey("PendingTarget")){r.pendingTarget=KOMEDiplomacyRelation.parse(n.getString("PendingTarget"));if(r.pendingTarget==KOMEDiplomacyRelation.NEUTRAL)throw new IllegalArgumentException("Pending target must increase relation");r.requestingFaction=KOMEAlliance.normalizeFactionKey(n.getString("RequestingFaction"));r.receivingFaction=KOMEAlliance.normalizeFactionKey(n.getString("ReceivingFaction"));r.requesterIdentity=n.getString("RequesterIdentity");r.requestedAt=n.getLong("RequestedAt");if(!r.requestingFaction.equals(r.factionA)&&!r.requestingFaction.equals(r.factionB))throw new IllegalArgumentException("Invalid diplomacy requester");if(!r.receivingFaction.equals(r.factionA)&&!r.receivingFaction.equals(r.factionB))throw new IllegalArgumentException("Invalid diplomacy receiver");}r.lastUpdatedBy=n.getString("LastUpdatedBy");r.updatedAt=n.getLong("UpdatedAt");return r;}
}
